9	function OnlineChessboard({ serverToken, roomId, onBackToList }) {
10	  const game = useOnlineGame({ serverToken, roomId });
11	
12	  const [draggedPiece, setDraggedPiece] = useState(null);
13	  const [draggedFrom, setDraggedFrom] = useState(null);
14	  const [validMoves, setValidMoves] = useState([]);
15	  const [promotionData, setPromotionData] = useState(null); // { from, to, piece }
16	
17	  const isMyTurn = game.myColor === game.currentTurn;
18	
19	  const handleDragStart = useCallback((squareIndex, piece) => {
20	    // Only allow dragging own pieces on own turn
21	    if (!isMyTurn) return;
22	    const isWhite = piece > 0;
23	    if ((game.myColor === 'white' && !isWhite) || (game.myColor === 'black' && isWhite)) return;
24	
25	    setDraggedPiece(piece);
26	    setDraggedFrom(squareIndex);
27	    setValidMoves(game.getValidMovesForSquare(squareIndex));
28	  }, [isMyTurn, game]);
29	
30	  const handleDragOver = (e) => {
31	    e.preventDefault();
32	  };
33	
34	  const handleDrop = useCallback(async (squareIndex) => {
35	    if (draggedFrom === null || draggedFrom === squareIndex) {
36	      setDraggedPiece(null);
37	      setDraggedFrom(null);
38	      setValidMoves([]);
39	      return;
40	    }
41	
42	    if (!validMoves.includes(squareIndex)) {
43	      setDraggedPiece(null);
44	      setDraggedFrom(null);
45	      setValidMoves([]);
46	      return;
47	    }
48	
49	    // Check if this is a promotion move (use client-side check for UX dialog)
50	    if (needsPromotion(draggedPiece, squareIndex)) {
51	      setPromotionData({ from: draggedFrom, to: squareIndex, piece: draggedPiece });
52	      setDraggedPiece(null);
53	      setDraggedFrom(null);
54	      setValidMoves([]);
55	      return;
56	    }
57	
58	    // Build UCI string
59	    const cols = 'abcdefgh';
60	    const fromStr = cols[draggedFrom % 8] + (8 - Math.floor(draggedFrom / 8));
61	    const toStr = cols[squareIndex % 8] + (8 - Math.floor(squareIndex / 8));
62	    const uci = fromStr + toStr;
63	
64	    // Play sound optimistically
65	    const isCapture = game.board[squareIndex] !== 0;
66	    if (isCapture) { playCaptureSound(); } else { playMoveSound(); }
