          <button className="back-button" onClick={onBackToList}>Back to Games</button>
          {game.room && (
            <span className="online-info">
              {game.room.white || '?'} vs {game.room.black || '?'}
              {game.room.isStockfish && ` (Stockfish Lv${game.room.stockfishLevel})`}
            </span>
          )}
        </div>
      </div>

      {gameStatus && (
